"use strict";

// Turn an arbitrary title into a URL slug.
//
// Rule: non-alphanumeric runs become "-" (trimmed at both ends), and the
// trailing year token (digits preceded by a separator) becomes "_YYYY".
// Example: "Quarterly Report 2026" -> "quarterly-report_2026".
function slugify(title) {
  const s = String(title);
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-(\d+)$/, "_$1");
}

module.exports = { slugify };

